        for (Enumeration<JarFile> e = jarFiles.elements(); e.hasMoreElements();) {
            JarFile jarFile = e.nextElement();
            try {
                jarFile.close();
            } catch (IOException ioe) {
                // ignore
            }
        }
        jarFiles = new Hashtable<File, JarFile>();
        if (project != null) {
            project.removeBuildListener(this);
        }
        project = null;
    }

