class UmlFactoryMDRImpl extends AbstractUmlModelFactoryMDR implements
        UmlFactory {

    /**
     * The logger.
     */
    private static final Logger LOG =
        Logger.getLogger(UmlFactoryMDRImpl.class.getName());

    /**
     * The model implementation.
