    protected void removeDiagram(ArgoDiagram d) {
        diagrams.remove(d);

        /* Remove the dependent
         * modelelements, such as the statemachine
         * for a statechartdiagram:
         */
        Object o = d.getDependentElement();
        if (o != null) {
