    this.decomManager = new DecommissionManager(namesystem, blockManager,
        heartbeatManager);
    this.fsClusterStats = newFSClusterStats();

    networktopology = NetworkTopology.getInstance(conf);

    this.defaultXferPort = NetUtils.createSocketAddr(
