        }
        if (this.legendLabelURLGenerator instanceof PublicCloneable) {
            clone.legendLabelURLGenerator = (PieURLGenerator)
                    ObjectUtilities.clone(this.legendLabelURLGenerator);
        }
        return clone;
    }

