    @Override
    public void addAnnotation(XYAnnotation annotation, Layer layer) {
        ParamChecks.nullNotPermitted(annotation, "annotation");
        if (layer.equals(Layer.FOREGROUND)) {
            this.foregroundAnnotations.add(annotation);
